import java.util.*;
import java.lang.*;
import java.io.*;

public class Ideone {
    public static void main(String[] args) throws java.lang.Exception {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        String s = in.next();

        boolean parenthesized = false;
        int outsideLongest = 0;
        int innerWords = 0;
        int cur = 0;

        for (int idx = 0; idx < n; ++idx) {
            char ch = s.charAt(idx);
            if (ch == '_') {
                if (parenthesized) {
                    if (cur > 0) {
                        innerWords++;
                    } else {
                        outsideLongest = Math.max(outsideLongest, cur);
                    }
                } else {
                    outsideLongest = Math.max(outsideLongest, cur);
                }
                cur = 0;
            } else if (ch == '(') {
                parenthesized = true;
                outsideLongest = Math.max(outsideLongest, cur);
                cur = 0;
            } else if (ch == ')') {
                parenthesized = false;
                if (cur > 0) {
                    innerWords++;
                }
                cur = 0;
            } else {
                cur++;
            }
        }

        outsideLongest = Math.max(outsideLongest, cur);
        System.out.println(outsideLongest + " " + innerWords);
    }
}
